B.aSC=new A.eY("kapadokya","Kapadokya","Cappadocia","Peri bacalar\u0131 milyonlarca y\u0131l \xf6nce volkanik k\xfcllerden olu\u015ftu.","The fairy chimneys formed from volcanic ash millions of years ago.")
B.aSO=new A.eY("pamukkale","Pamukkale","Pamukkale","Beyaz travertenler, kire\xe7li s\u0131cak suyun binlerce y\u0131l akmas\u0131yla olu\u015ftu.","The white terraces were built by warm, mineral-rich water over thousands of years.")
B.aSR=new A.eY("efes","Efes","Ephesus","Celsus K\xfct\xfcphanesi bir zamanlar 12.000 par\u015f\xf6mene ev sahipli\u011fi yapt\u0131.","The Library of Celsus once held about 12,000 scrolls.")
B.aSM=new A.eY("nemrut","Nemrut Da\u011f\u0131","Mount Nemrut","Zirvedeki dev heykellerde g\xfcn do\u011fumu ayr\u0131 bir g\xfczel.","Sunrise over the giant stone heads at the summit is famous.")
B.aSQ=new A.eY("sumela","S\xfcmela Manast\u0131r\u0131","Sumela Monastery","Sarp bir kayal\u0131\u011fa, denizden 1.200 metre y\xfckse\u011fe kurulmu\u015f.","It clings to a cliff about 1,200 metres above sea level.")
B.aSP=new A.eY("uzungol","Uzung\xf6l","Uzung\xf6l","G\xf6l, da\u011fdan d\xfc\u015fen kayalar\u0131n dereyi kapatmas\u0131yla olu\u015ftu.","The lake formed when a landslide dammed a mountain stream.")
B.aSE=new A.eY("galata","Galata Kulesi","Galata Tower","Hezarfen Ahmed \xc7elebi'nin buradan u\xe7tu\u011fu anlat\u0131l\u0131r.","Legend says Hez\xe2rfen Ahmed \xc7elebi flew from here across the Bosphorus.")
B.aSV=new A.eY("ayasofya","Ayasofya","Hagia Sophia","Kubbesi yakla\u015f\u0131k bin y\u0131l d\xfcnyan\u0131n en b\xfcy\xfck kubbesiydi.","Its dome was the largest in the world for nearly a thousand years.")
B.aSH=new A.eY("olimpos","Olimpos","Olympos","Yak\u0131ndaki Yanarta\u015f'ta binlerce y\u0131ld\u0131r s\xf6nmeyen alevler yanar.","Nearby Chimaera has flames that have burned for thousands of years.")
B.aSN=new A.eY("kas","Ka\u015f","Ka\u015f","Bat\u0131k Kekova \u015fehrinin kal\u0131nt\u0131lar\u0131 berrak suyun alt\u0131ndan g\xf6r\xfcn\xfcr.","The ruins of sunken Kekova can be seen through the clear water.")
B.aST=new A.eY("safranbolu","Safranbolu","Safranbolu","Ad\u0131n\u0131 bir zamanlar burada yeti\u015ftirilen safrandan al\u0131r.","It takes its name from the saffron once grown here.")
B.aSD=new A.eY("mardin","Mardin","Mardin","Ta\u015f evler, Mezopotamya ovas\u0131na bakan bir yamaca basamak basamak dizilir.","Stone houses step down a hill overlooking the Mesopotamian plain.")
B.aSI=new A.eY("ani","Ani Harabeleri","Ani",'"Bin bir kilise \u015fehri" olarak bilinirdi.','It was known as the "city of 1,001 churches".')
B.aSK=new A.eY("gobekli","G\xf6beklitepe","G\xf6bekli Tepe","Yakla\u015f\u0131k 11.000 y\u0131ll\u0131k; Stonehenge'den 6.000 y\u0131l daha eski.","About 11,000 years old, some 6,000 years older than Stonehenge.")
B.aSF=new A.eY("abant","Abant G\xf6l\xfc","Lake Abant","Sonbaharda \xe7evresindeki ormanlar sar\u0131 ve k\u0131rm\u0131z\u0131ya d\xf6ner.","In autumn the forests around it turn gold and red.")
B.aSW=new A.eY("bozcaada","Bozcaada","Bozcaada","R\xfczg\xe2r\u0131 ve ba\u011flar\u0131yla \xfcnl\xfc k\xfc\xe7\xfck bir Ege adas\u0131.","A small Aegean island known for its wind and vineyards.")
B.aSJ=new A.eY("ayder","Ayder Yaylas\u0131","Ayder Plateau","Bulutlar\u0131n aras\u0131nda, kapl\u0131cas\u0131 olan bir yayla.","A highland meadow above the clouds, with hot springs.")
B.aSU=new A.eY("cunda","Cunda","Cunda Island","Ta\u015f evleri ve zeytinlikleriyle Ayval\u0131k'\u0131n kar\u015f\u0131s\u0131nda.","Stone houses and olive groves across from Ayval\u0131k.")
B.aSL=new A.eY("zeugma","Zeugma","Zeugma","\xc7ingene K\u0131z\u0131 mozai\u011fi buradan \xe7\u0131kar\u0131ld\u0131.",'The famous "Gypsy Girl" mosaic was found here.')
B.aSz=new A.eY("ishak","\u0130shak Pa\u015fa Saray\u0131","Ishak Pasha Palace","A\u011fr\u0131 Da\u011f\u0131'na bakan sarayda y\xfczy\u0131llar \xf6nce merkezi \u0131s\u0131tma vard\u0131.","Facing Mount Ararat, it had central heating centuries ago.")
B.aSG=new A.eY("salda","Salda G\xf6l\xfc","Lake Salda",'Beyaz kumsal\u0131 ve turkuaz suyuyla "T\xfcrkiye\'nin Maldivleri" denir.','Its white shores and turquoise water earned it the name "Turkey\'s Maldives".')
B.aSS=new A.eY("amasra","Amasra","Amasra","Karadeniz'e uzanan kalesi ve iki liman\u0131yla \xfcnl\xfc.","Known for its castle and twin harbours on the Black Sea.")
B.aSB=new A.eY("patara","Patara","Patara","T\xfcrkiye'nin en uzun kumsallar\u0131ndan biri; caretta carettalar burada yumurtlar.","One of Turkey's longest beaches, where loggerhead turtles nest.")
B.aSA=new A.eY("van","Van G\xf6l\xfc","Lake Van","T\xfcrkiye'nin en b\xfcy\xfck g\xf6l\xfc; suyu sodal\u0131 oldu\u011fu i\xe7in sabun gibi k\xf6p\xfcr\xfcr.","Turkey's largest lake; its soda-rich water foams like soap.")
